try {
  const lockPid = parseInt(fs.readFileSync(LOCK_FILE, 'utf8').trim(), 10);

  if (!isNaN(lockPid)) {

    try {
      process.kill(lockPid, 0);
    } catch(err) {

      if (err.code === 'ESRCH') {
        isRunning = false;
      }
    }

    if (!isRunning) {
      console.warn(`[CITY-SPAWN] Found stale lock file for non-existent PID ${lockPid}. Removing...`);
      fs.unlinkSync(LOCK_FILE);
      continue; // Retry acquisition immediately
    }
  }

  // ...other error paths proceed as expected

